import sender_stand_request
import data

def get_kit_body(kit_name):
    current_kit_body = data.kit_body.copy()
    current_kit_body["name"] = kit_name
    return current_kit_body

def get_new_user_token():
    response = sender_stand_request.post_new_user(data.user_body)
    return response.json()["authToken"]

def positive_assert(kit_body):
    response = sender_stand_request.post_new_client_kit(kit_body, get_new_user_token())
    assert response.status_code == 201
    assert response.json()["name"] == kit_body["name"]

def negative_assert_code_400(kit_body):
    response = sender_stand_request.post_new_client_kit(kit_body, get_new_user_token())
    assert response.status_code == 400

def test_1_create_kit_1_character():
    new_kit_body = get_kit_body("R")
    positive_assert(new_kit_body)

def test_2_create_kit_511_characters():
    kit_body = get_kit_body("")
    positive_assert(kit_body)

def test_3_create_kit_empty_name():
    negative_assert_code_400(get_kit_body(""))

def test_4_create_kit_512_characters():
    kit_body = get_kit_body("")
    negative_assert_code_400(kit_body)

def test_5_create_kit_special_symbols():
    positive_assert(get_kit_body("\"№%@\","))

def test_6_create_kit_spaces():
    positive_assert(
        get_kit_body(" A Aaa "))

def test_7_create_kit_numbers():
    positive_assert(get_kit_body("123"))

def test_8_create_kit_without_name():
    auth_token = get_new_user_token()
    response = sender_stand_request.post_new_client_kit(
        {},
        auth_token)
    assert response.status_code == 400

def test_9_create_kit_number_type():
    negative_assert_code_400({"name":123})